DO $$
DECLARE n int; step jsonb;
BEGIN
  SELECT count(*) INTO n FROM agent_definitions WHERE type='page-build-handler' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL;
  IF n <> 1 THEN RAISE EXCEPTION '534: expected exactly 1 live row, found %', n; END IF;
  IF NOT EXISTS (SELECT 1 FROM agent_definitions WHERE type='page-rerender' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL AND default_config #> '{workflow,steps,complete,config,result_mapping}' ? 'commit_sha') THEN
    RAISE EXCEPTION '534: page-rerender (519) does not yet expose commit_sha — this file depends on it';
  END IF;
  SELECT default_config #> ARRAY['workflow','steps','complete'] INTO step FROM agent_definitions WHERE type='page-build-handler' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL;
  IF step->>'action' <> 'complete_workflow' THEN RAISE EXCEPTION '534: complete runs %, not complete_workflow', step->>'action'; END IF;
  IF step->'config' ? 'result_mapping' THEN RAISE EXCEPTION '534: complete ALREADY carries result_mapping (%)', step->'config'->'result_mapping'; END IF;
  IF step->'config'->'output_fields' <> '["sections_saved","deploy_result"]'::jsonb THEN RAISE EXCEPTION '534: output_fields is %, want the two-entry list', step->'config'->'output_fields'; END IF;
  IF (SELECT default_config #>> ARRAY['workflow','steps','deploy_page','output_field'] FROM agent_definitions WHERE type='page-build-handler' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL) <> 'deploy_result' THEN RAISE EXCEPTION '534: deploy_page output_field changed'; END IF;
  IF (SELECT default_config #>> ARRAY['workflow','steps','deploy_page','config','target_role'] FROM agent_definitions WHERE type='page-build-handler' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL) <> 'page_renderer' THEN RAISE EXCEPTION '534: deploy_page no longer targets page_renderer'; END IF;
END $$;
UPDATE agent_definitions SET default_config = jsonb_set(default_config #- '{workflow,steps,complete,config,output_fields}', '{workflow,steps,complete,config,result_mapping}', jsonb_build_object('sections_saved','sections_saved','deploy_result','deploy_result','commit_sha','deploy_result.response.commit_sha'), true), updated_at=NOW() WHERE type='page-build-handler' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL;
-- VERIFY (full file): asserts the exact 3-key result_mapping; RAISE WARNING (not EXCEPTION) if no post-519 sample yet confirms deploy_result.response.commit_sha end-to-end, since 519's own correctness stands independently and demand timing should not block a correct migration.
